		if ( fade <= 0.0 || p.z >= 1.0 || p.z <= 0.0 ) return 1.0;
		float A = p.z / ( 1.0 - GS_SPOT_NEAR / w ); // far / ( far - near )
		vec2 texel = 1.0 / mapSize;
		float metresPerUv = 2.0 * tanHalf * w;
