// A severed part is cut away, raggedly, a little past the joint; the stump is closed by a cap of
// flesh inside the limb (eyes.js: buildCore). The jaw alone is not cut: its skin is the wound.
bool sChCut(vec3 pr, float n) {
  float st = sChStump(pr);
  if (st <= 0.0) return false;
  if (uChSever[0] > 0.25 && uChSever[0] < 0.75 && pr.y > 1.5) return false;
  return st > 1.0 + 0.1 * n;
}

#ifdef CLOTH_SLOTS
uniform float uClKindA[8];
uniform float uClTornA[8];
int gSlot = 0;
#define CL_KIND uClKindA[gSlot]
#define CL_TORN uClTornA[gSlot]
#else
uniform float uClKind;
uniform float uClTorn;
#define CL_KIND uClKind
#define CL_TORN uClTorn
#endif
uniform float uClUv;
// threads per metre
float sClothT() {
  int k = int(CL_KIND + 0.5);
  return k == 0 ? 1500.0 : k == 1 ? 1000.0 : k == 2 ? 620.0 : k == 3 ? 900.0 : k == 4 ? 1100.0 : k == 6 ? 1400.0 : k == 7 ? 420.0 : 520.0;
