struct Surf { vec3 albedo; float rough; float metal; vec3 grad; vec2 dH; vec3 emissive; float alpha; float ao; };

// per-fragment context, set once in main()
vec3 gP;    // noise-space position (world, or object/rest space) plus the seed offset
vec3 gN;    // geometric normal in noise space
vec3 gNw;   // geometric normal in world space
vec3 gWp;   // world position
vec3 gV;    // world direction to the camera
vec4 gA;    // aSurf vertex masks: x wear/edge, y blood, z grip zone
float gNdv;

#define NZ_BASE 8.0
#define NZ_GRAD 4.0
#define NZ_VORO 16.0
// SURF_Q: 2 = high, 1 = medium, 0 = low (from G.quality). Optional layers are dropped below 2.
#ifndef SURF_Q
  #define SURF_Q 2
#endif

float gFp = 0.001;

vec3 sHash3(ivec3 c) {
  uvec3 x = uvec3(c);
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  return vec3(x) * (1.0 / 4294967295.0);
}
float sHash1(ivec3 c) { return sHash3(c).x; }
vec3 sHash2(ivec2 c) { return sHash3(ivec3(c, 7)); }

float sFade(float freq) { return 1.0 - smoothstep(0.16, 0.5, gFp * freq); }

const mat3 S_ROT = mat3(0.00, 0.80, 0.60, -0.80, 0.36, -0.48, -0.60, -0.48, 0.64);

// ---- texture-backed noise (noiseTex.js). These replace the procedural functions above at runtime:
// one fetch each, with the mip level chosen from gFp, so they are safe inside branches and fade to
// their mean with distance by themselves.
uniform highp sampler3D tNzA;
uniform highp sampler3D tNzB;
float gLod = 0.0;      // mip level of a volume sampled at one tile per unit of noise space

// fbm, three octaves up from 'freq' cycles per unit: x = value (mean 0.5), yzw = gradient per unit of p
vec4 sFbmD(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  vec4 t = textureLod(tNzA, p * sc, gLod + log2(sc));
  return vec4(t.x, (t.yzw - 0.5) * (2.0 * NZ_GRAD * freq));
}
float sFbm(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  return textureLod(tNzA, p * sc, gLod + log2(sc)).x;
}
// the same field with different frequencies across and along a direction
vec4 sAnisoD(vec3 p, vec3 dir, float perp, float along) {
  vec3 q = p * perp + dir * (dot(p, dir) * (along - perp));
  vec4 t = textureLod(tNzA, q * (1.0 / NZ_BASE), gLod + log2(max(perp, along) * (1.0 / NZ_BASE)));
  vec3 g = (t.yzw - 0.5) * (2.0 * NZ_GRAD);
  return vec4(t.x, g * perp + dir * (dot(g, dir) * (along - perp)));
}
// one octave of gradient noise; q is in lattice cells, fmax the largest scale applied to get there
float sNoise(vec3 q, float fmax) {
  return textureLod(tNzB, q * (1.0 / NZ_BASE), gLod + log2(fmax * (1.0 / NZ_BASE))).a;
}
// voronoi, 'cells' per unit: x = F1, y = F2 - F1 (0 on cell edges), z = cell id, w = unrelated noise
vec4 sVoro(vec3 p, float cells) {
  float sc = cells * (1.0 / NZ_VORO);
  return textureLod(tNzB, p * sc, gLod + log2(sc));
}
// Sparse round domes (water beads, sand grains, pills): jittered spheres on a 3D grid, cut by the
// surface. Analytic and exact at any distance from one hash: each sphere stays inside its own cell, so
// only that cell is tested. 'amount' is the fraction of cells that hold one.
// x = coverage 0..1, y = dome height 0..1, z = radius in cells, w = per-dome random.
vec3 gDomeSlope = vec3(0.0);   // slope of the last dome evaluated (noise space, per cell)
vec4 sDomes(vec3 p, float cells, float amount) {
  vec3 q = p * cells;
  vec3 fl = floor(q);
  vec3 h = sHash3(ivec3(fl));
  float pick = fract(h.x * 7.31 + h.y * 3.17);
  vec3 r = q - (fl + 0.5 + (h - 0.5) * 0.4);
  float rad = 0.12 + 0.17 * fract(h.z * 5.3 + pick);
  float t = 1.0 - dot(r, r) / (rad * rad);
  gDomeSlope = vec3(0.0);
  if (pick > amount || t <= 0.0) return vec4(0.0, 0.0, rad, 0.0);
  gDomeSlope = -3.0 * t * r / rad;
  return vec4(smoothstep(0.0, 0.25, t), t, rad, fract(h.z * 11.3));
}
vec3 gGradX = vec3(0.0);       // extra analytic slope from shared layers (beads), added to Surf.grad
float gHt = 0.0;       // extra relief in metres, differentiated on screen once (beads, rivulets, pits)

// Straight hairline scratches along 'dir': the one-octave field squeezed along that direction, so
// each lattice cell becomes a long thin sliver, and only the brightest slivers are kept.
float sScratches(vec3 p, vec3 dir, float across, float along, float density) {
  float f = sFade(across);
  if (f <= 0.0) return 0.0;
  float n = sNoise(p * across - dir * dot(p, dir) * (across - along), across);
  return smoothstep(1.0 - density, 1.0 - density * 0.6, n) * f;
}

// Thin winding line along the 0.5 iso-contour of a noise field: returns distance to the line in the
// field's own space units (metres if p is metres), using the analytic gradient for constant width.
float sIsoDist(vec4 n) { return abs(n.x - 0.5) / max(length(n.yzw), 1e-4); }

// B-spline bicubic from four bilinear taps. The texture must use linear filtering.
vec4 sBicubic(sampler2D t, vec2 uv, float res) {
  vec2 st = uv * res - 0.5; vec2 i = floor(st); vec2 f = st - i;
  vec2 f2 = f * f, f3 = f2 * f;
  vec2 w0 = (1.0 - f) * (1.0 - f) * (1.0 - f) / 6.0;
  vec2 w1 = (3.0 * f3 - 6.0 * f2 + 4.0) / 6.0;
  vec2 w3 = f3 / 6.0;
  vec2 w2 = 1.0 - w0 - w1 - w3;
  vec2 g0 = w0 + w1, g1 = w2 + w3;
  vec2 h0 = (i - 0.5 + w1 / g0) / res, h1 = (i + 1.5 + w3 / g1) / res;
  return g0.y * (g0.x * texture2D(t, h0) + g1.x * texture2D(t, vec2(h1.x, h0.y)))
       + g1.y * (g0.x * texture2D(t, vec2(h0.x, h1.y)) + g1.x * texture2D(t, h1));
}

float sLuma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
vec3 sSat(vec3 c, float k) { return max(mix(vec3(sLuma(c)), c, k), 0.0); }


// ---- rain ----
// how much rain reaches this fragment: up-facing most, undersides least, nothing under shelter
float sExposure() { return (1.0 - uShelter) * mix(0.25, 1.0, smoothstep(-0.35, 0.65, gNw.y)); }
// 1 where the object meets the ground, gone by about half a metre, with a broken top edge
float gSplash = -1.0;     // computed once per fragment; several layers ask for it
float sSplashBand() {
  if (gSplash >= 0.0) return gSplash;
  float h = gWp.y - uGroundY;
  gSplash = 0.0;
  if (h < 0.8 && uSplash > 0.0) gSplash = uSplash * (1.0 - smoothstep(0.02, 0.3 + 0.35 * sNoise(gP * vec3(7.0, 2.0, 7.0), 7.0), h));
  return gSplash;
}
float sWetAmount() { return clamp(uWetness * max(sExposure(), sSplashBand() * 0.9), 0.0, 1.0); }

// Water beads standing on a surface: coverage, and their slope added to the normal. No fetch.
float sBeadLayer(vec3 p, float cells, float amount, float lift) {
  vec4 b = sDomes(p, cells, amount);
  gGradX += gDomeSlope * lift;
  return b.x;
}

// Non-porous surfaces: water sits on top as a film, beads, and rivulets on vertical faces.
// 'lo' is any slow noise value the caller already has (it places the film).
void sWetHard(inout Surf s, float w, float lo) {
  if (w < 0.01) return;
  float up = smoothstep(0.3, 0.9, gNw.y);
  float f1 = sFade(260.0);
  float film = w * mix(0.25, 0.85, up) * smoothstep(0.3, 0.7, lo * 0.6 + w * 0.5);
  float gloss = film;
  #if SURF_Q > 0
  if (f1 > 0.0) gloss = max(gloss, sBeadLayer(gP, 120.0, 0.5 * w, 0.9) * f1);
  #endif
  #if SURF_Q > 1
  if (sFade(900.0) > 0.3) gloss = max(gloss, sBeadLayer(gP + 3.7, 430.0, 0.65 * w, 0.9));
  #endif
  #if !defined(SURF_LOCAL) && SURF_Q > 0
  float side = 1.0 - smoothstep(0.25, 0.75, abs(gNw.y));
  if (side > 0.01 && uRain > 0.0) {
    float r = sNoise(vec3(gP.x * 64.0, gP.y * 2.2 + uTime * 0.35, gP.z * 64.0), 64.0);
    float riv = smoothstep(0.62, 0.74, r) * side * w * uRain;
    gHt += riv * 0.0004;
    gloss = max(gloss, riv);
  }
  #endif
  s.rough = mix(s.rough, 0.06, gloss);
  // beyond the range where beads resolve they average into a general sheen
  s.rough = mix(s.rough, max(s.rough * 0.7, 0.14), w * (1.0 - f1) * 0.8);
  s.albedo *= 1.0 - 0.12 * film;
}

// Porous surfaces soak: darker, more saturated, smoother. The soak has an edge: rain reaches some
// of a wall and not the rest, and on vertical faces it comes down in broad streaks.
// 'lo' is a slow noise value and 'streak' a vertical-streak value the caller already has.
void sWetPorous(inout Surf s, float w, float porosity, float lo, float streak) {
  if (w < 0.01) return;
  float side = 1.0 - smoothstep(0.3, 0.8, abs(gN.y));
  float n = mix(lo, lo * 0.5 + 0.5 * streak, side);
  float k = smoothstep(0.62, 0.38, n - (w - 0.5) * 0.9) * smoothstep(0.0, 0.25, w);
  s.albedo = sSat(s.albedo, 1.0 + 0.3 * k) * mix(1.0, 1.0 - 0.6 * porosity, k);
  s.rough = mix(s.rough, s.rough * 0.45, k);
}

// ---- paint damage, shared by painted metal and painted concrete ----
// One scalar field; rising through it you cross stained paint (halo), then the primer rim, then the
// substrate. 'grad' is the slope of the paint film's broken edge.
struct Chip { float bare; float primer; float halo; vec3 grad; };
float sChipTh(float wear) { return mix(0.74, 0.47, wear) - 0.07 * sSplashBand(); }
// two fetches: the broad field that decides where paint has failed, and the ragged edge detail
float gChipLo = 0.5;    // the broad half of the chip field, for callers that look nearby (rust runs)
vec4 sChipField(vec3 p, float scale) {
  vec4 a = sFbmD(p + 31.7, 1.1 * scale);
  gChipLo = a.x;
  vec4 b = sFbmD(S_ROT * p, 13.0 * scale);
  return vec4(a.x * 0.42 + b.x * 0.58, a.yzw * 0.42 + (b.yzw * S_ROT) * 0.58);
}
Chip sChips(vec3 p, float wear, float scale) {
  Chip k = Chip(0.0, 0.0, 0.0, vec3(0.0));
  if (wear <= 0.001) return k;
  vec4 n = sChipField(p, scale);
  #if SURF_Q > 1
  // the stored field is three octaves; a finer copy keeps chip outlines ragged up close
  vec4 d = sFbmD(p + 5.3, 60.0 * scale);
  n += vec4(d.x - 0.5, d.yzw) * 0.2;
  #endif
  float th = sChipTh(wear);
  float aa = 0.006 + length(n.yzw) * gFp * 1.2;
  k.bare = smoothstep(th, th + aa, n.x);
  k.primer = smoothstep(th - 0.01, th - 0.01 + aa, n.x);
  k.halo = smoothstep(th - 0.16, th, n.x);
  float e = k.primer * (1.0 - k.primer) * 4.0;
  vec3 g = -n.yzw * (e * 1.5 / aa) * 0.00012;
  k.grad = g / max(1.0, length(g));
  return k;
}


uniform float uGFinish;
uniform float uGWear;
uniform float uGOil;
uniform float uGStud;
uniform vec3 uGBrush;
uniform vec3 uGPoly;
uniform vec3 uGripMin[4];
uniform vec3 uGripMax[4];
uniform int uGripCount;
void surfaceMain(inout Surf s) {
  vec3 p = gP;
  // convex edges: signed curvature from screen derivatives (1/m), plus the baked mask
  vec3 dpx = dFdx(vSP), dpy = dFdy(vSP), dnx = dFdx(gN), dny = dFdy(gN);
  float curv = (dot(dnx, dpx) + dot(dny, dpy)) / max(dot(dpx, dpx) + dot(dpy, dpy), 1e-12);
  float edge = clamp(smoothstep(120.0, 700.0, curv) + gA.x, 0.0, 1.0);

  vec4 wn = sFbmD(p + 19.0, 55.0);
  #if SURF_Q > 0
  vec4 wl = sFbmD(S_ROT * p + 3.0, 9.0);
  #else
  vec4 wl = wn.xzwy;
  #endif
  vec3 bd = normalize(uGBrush);

  // wear: edges first, then patches across the flats. Handling scratches pull the wear boundary
  // out into hairlines.
  float hair = 0.0;
  #if SURF_Q > 0
  hair = sScratches(p + 5.0, normalize(bd + vec3(0.15, 0.3, 0.0)), 2400.0, 30.0, 0.3);
  #endif
  #if SURF_Q > 1
  hair = max(hair, sScratches(p + 11.0, normalize(vec3(0.3, 1.0, 0.2)), 2400.0, 45.0, 0.22));
  #endif
  bool blued = uGFinish > 2.5 && uGFinish < 3.5;
  // bluing thins in patches along an edge, not as an even bright line
  float edgeK = blued ? 0.75 * smoothstep(0.42, 0.72, wn.x * 0.55 + wl.x * 0.45) : 0.7;
  float field = wn.x * 0.55 + wl.x * 0.45 + edge * edgeK + hair * 0.16;
  float th = mix(1.05, 0.5, uGWear);
  float worn = smoothstep(th, th + 0.025, field);

  // brushed grain: the fbm field squeezed along the brush direction. Two widths of line, so the
  // grain reads at arm's length and still resolves against the eye. Only where steel shows.
  float fB = sFade(900.0);
  float br = 0.5; vec3 brG = vec3(0.0);
  bool steelShows = (uGFinish < 1.5 && (uGFinish > 0.5 || worn > 0.0)) || (blued && worn > 0.0);
  #if SURF_Q < 1
  steelShows = false;
  #endif
  if (fB > 0.0 && steelShows) {
    vec4 b1 = sAnisoD(p, bd, 900.0, 20.0);
    br = b1.x; brG = b1.yzw * 2.2;
    #if SURF_Q > 1
    float f2 = sFade(2600.0);
    if (f2 > 0.0) {
      vec4 b2 = sAnisoD(p + 7.0, bd, 2600.0, 45.0);
      br = b1.x * 0.6 + b2.x * 0.4; brG += b2.yzw * f2;
    }
    #endif
    br = mix(0.5, br, fB); brG *= fB;
  }
  vec3 steel = vec3(0.55, 0.56, 0.58);
  vec3 alb; float rough; float metal; vec3 g = vec3(0.0);

  if (uGFinish < 0.5) {
    #if SURF_Q > 0
    vec4 mg = sFbmD(p, 650.0);
    #else
    vec4 mg = vec4(0.5, 0.0, 0.0, 0.0);
    #endif
