	// Orthographic (moon). Depths are the 0..1 map values; linear in metres.
	float gsMoonShadow( sampler2D map, vec2 mapSize, float uvPerMetre, float depthRange, float tanAngle, vec4 coord ) {
		vec3 p = coord.xyz / coord.w;
