	float gsSpotShadow( sampler2D map, vec2 mapSize, float tanHalf, float biasMetres, float sourceRadius, vec4 coord ) {
		float w = coord.w;
		if ( w <= GS_SPOT_NEAR * 1.05 ) return 1.0;
