  vec2 pb = sChPartBlood(pr);
  float fresh = 0.0;
  if (pb.x > 0.0 || crater > 0.0 || wd.x < 2.2) {
    float pool = clamp(cavF * 0.9 + cav * 0.45 + (blot - 0.5) * 0.9, 0.0, 1.5);
