  float gr = uChGrime * clamp(sSplashBand() * 0.8 + cav * 0.5 + (blot - 0.6) * 0.8, 0.0, 1.0) * (1.0 - special);
  alb = mix(alb, vec3(0.03, 0.026, 0.02), gr * 0.55);
  rough = mix(rough, 0.8, gr * 0.5);
