    rough = mix(rough, rough * 0.66, w * (1.0 - crater));
    #if SURF_Q > 0
    float fb = sFade(300.0) * (1.0 - uChFar);
    if (fb > 0.0) { float bead = sBeadLayer(gP, 200.0, 0.1 * w, 0.3) * fb; rough = mix(rough, 0.1, bead * 0.7); }
    #endif
