      sp += exp(-across * across / (w * w)) * exp(-along * (k == 0 ? 4.5 : 7.0)) * (k == 0 ? 1.0 : 0.6);
    }
    float streak = exp(-abs(vUv.y) * 70.0) * exp(-abs(vUv.x) * 3.0);
    float veil = exp(-r * 14.0) * 0.5 + exp(-r * 4.0) * 0.03;
