	// d(depth)/d(uv) of the receiver's plane in shadow-map space, from screen-space derivatives
	vec2 gsPlaneGradient( vec2 uv, float depth ) {
		vec2 dx = dFdx( uv ); vec2 dy = dFdy( uv );
