			vec2 c = gsTexelCentre( p.xy + gsDisk( i, GS_BLOCKER_TAPS, phi ) * searchR, mapSize );
			float wb = GS_SPOT_NEAR / max( 1.0 - texture2D( map, c ).r / A, 1e-6 );
