			vec2 f = fract( st );
			vec2 c = ( floor( st ) + 0.5 ) * texel;
			lit += mix( mix( GS_MOON_CMP( c ), GS_MOON_CMP( c + vec2( texel.x, 0.0 ) ), f.x ),
				mix( GS_MOON_CMP( c + vec2( 0.0, texel.y ) ), GS_MOON_CMP( c + texel ), f.x ), f.y );
