// fbm, three octaves up from 'freq' cycles per unit: x = value (mean 0.5), yzw = gradient per unit of p
vec4 sFbmD(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  vec4 t = textureLod(tNzA, p * sc, gLod + log2(sc));
  return vec4(t.x, (t.yzw - 0.5) * (2.0 * NZ_GRAD * freq));
}
float sFbm(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  return textureLod(tNzA, p * sc, gLod + log2(sc)).x;
}
// the same field with different frequencies across and along a direction
vec4 sAnisoD(vec3 p, vec3 dir, float perp, float along) {
  vec3 q = p * perp + dir * (dot(p, dir) * (along - perp));
  vec4 t = textureLod(tNzA, q * (1.0 / NZ_BASE), gLod + log2(max(perp, along) * (1.0 / NZ_BASE)));
  vec3 g = (t.yzw - 0.5) * (2.0 * NZ_GRAD);
  return vec4(t.x, g * perp + dir * (dot(g, dir) * (along - perp)));
}
// one octave of gradient noise; q is in lattice cells, fmax the largest scale applied to get there
float sNoise(vec3 q, float fmax) {
  return textureLod(tNzB, q * (1.0 / NZ_BASE), gLod + log2(fmax * (1.0 / NZ_BASE))).a;
}
// voronoi, 'cells' per unit: x = F1, y = F2 - F1 (0 on cell edges), z = cell id, w = unrelated noise
vec4 sVoro(vec3 p, float cells) {
  float sc = cells * (1.0 / NZ_VORO);
  return textureLod(tNzB, p * sc, gLod + log2(sc));
}
// Sparse round domes (water beads, sand grains, pills): jittered spheres on a 3D grid, cut by the
// surface. Analytic and exact at any distance from one hash: each sphere stays inside its own cell, so
// only that cell is tested. 'amount' is the fraction of cells that hold one.
// x = coverage 0..1, y = dome height 0..1, z = radius in cells, w = per-dome random.
vec3 gDomeSlope = vec3(0.0);   // slope of the last dome evaluated (noise space, per cell)
vec4 sDomes(vec3 p, float cells, float amount) {
  vec3 q = p * cells;
  vec3 fl = floor(q);
  vec3 h = sHash3(ivec3(fl));
  float pick = fract(h.x * 7.31 + h.y * 3.17);
  vec3 r = q - (fl + 0.5 + (h - 0.5) * 0.4);
  float rad = 0.12 + 0.17 * fract(h.z * 5.3 + pick);
  float t = 1.0 - dot(r, r) / (rad * rad);
  gDomeSlope = vec3(0.0);
  if (pick > amount || t <= 0.0) return vec4(0.0, 0.0, rad, 0.0);
  gDomeSlope = -3.0 * t * r / rad;
  return vec4(smoothstep(0.0, 0.25, t), t, rad, fract(h.z * 11.3));
}
vec3 gGradX = vec3(0.0);       // extra analytic slope from shared layers (beads), added to Surf.grad
float gHt = 0.0;       // extra relief in metres, differentiated on screen once (beads, rivulets, pits)

// Straight hairline scratches along 'dir': the one-octave field squeezed along that direction, so
// each lattice cell becomes a long thin sliver, and only the brightest slivers are kept.
float sScratches(vec3 p, vec3 dir, float across, float along, float density) {
  float f = sFade(across);
  if (f <= 0.0) return 0.0;
  float n = sNoise(p * across - dir * dot(p, dir) * (across - along), across);
  return smoothstep(1.0 - density, 1.0 - density * 0.6, n) * f;
}

// Thin winding line along the 0.5 iso-contour of a noise field: returns distance to the line in the
// field's own space units (metres if p is metres), using the analytic gradient for constant width.
float sIsoDist(vec4 n) { return abs(n.x - 0.5) / max(length(n.yzw), 1e-4); }

// B-spline bicubic from four bilinear taps. The texture must use linear filtering.
vec4 sBicubic(sampler2D t, vec2 uv, float res) {
  vec2 st = uv * res - 0.5; vec2 i = floor(st); vec2 f = st - i;
  vec2 f2 = f * f, f3 = f2 * f;
  vec2 w0 = (1.0 - f) * (1.0 - f) * (1.0 - f) / 6.0;
  vec2 w1 = (3.0 * f3 - 6.0 * f2 + 4.0) / 6.0;
  vec2 w3 = f3 / 6.0;
  vec2 w2 = 1.0 - w0 - w1 - w3;
  vec2 g0 = w0 + w1, g1 = w2 + w3;
  vec2 h0 = (i - 0.5 + w1 / g0) / res, h1 = (i + 1.5 + w3 / g1) / res;
  return g0.y * (g0.x * texture2D(t, h0) + g1.x * texture2D(t, vec2(h1.x, h0.y)))
       + g1.y * (g0.x * texture2D(t, vec2(h0.x, h1.y)) + g1.x * texture2D(t, h1));
}

float sLuma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
vec3 sSat(vec3 c, float k) { return max(mix(vec3(sLuma(c)), c, k), 0.0); }


// ---- rain ----
// how much rain reaches this fragment: up-facing most, undersides least, nothing under shelter
float sExposure() { return (1.0 - uShelter) * mix(0.25, 1.0, smoothstep(-0.35, 0.65, gNw.y)); }
// 1 where the object meets the ground, gone by about half a metre, with a broken top edge
float gSplash = -1.0;     // computed once per fragment; several layers ask for it
float sSplashBand() {
  if (gSplash >= 0.0) return gSplash;
  float h = gWp.y - uGroundY;
  gSplash = 0.0;
  if (h < 0.8 && uSplash > 0.0) gSplash = uSplash * (1.0 - smoothstep(0.02, 0.3 + 0.35 * sNoise(gP * vec3(7.0, 2.0, 7.0), 7.0), h));
  return gSplash;
}
float sWetAmount() { return clamp(uWetness * max(sExposure(), sSplashBand() * 0.9), 0.0, 1.0); }

// Water beads standing on a surface: coverage, and their slope added to the normal. No fetch.
float sBeadLayer(vec3 p, float cells, float amount, float lift) {
  vec4 b = sDomes(p, cells, amount);
  gGradX += gDomeSlope * lift;
  return b.x;
}

// Non-porous surfaces: water sits on top as a film, beads, and rivulets on vertical faces.
// 'lo' is any slow noise value the caller already has (it places the film).
void sWetHard(inout Surf s, float w, float lo) {
  if (w < 0.01) return;
  float up = smoothstep(0.3, 0.9, gNw.y);
  float f1 = sFade(260.0);
  float film = w * mix(0.25, 0.85, up) * smoothstep(0.3, 0.7, lo * 0.6 + w * 0.5);
  float gloss = film;
  #if SURF_Q > 0
  if (f1 > 0.0) gloss = max(gloss, sBeadLayer(gP, 120.0, 0.5 * w, 0.9) * f1);
  #endif
  #if SURF_Q > 1
  if (sFade(900.0) > 0.3) gloss = max(gloss, sBeadLayer(gP + 3.7, 430.0, 0.65 * w, 0.9));
  #endif
  #if !defined(SURF_LOCAL) && SURF_Q > 0
  float side = 1.0 - smoothstep(0.25, 0.75, abs(gNw.y));
  if (side > 0.01 && uRain > 0.0) {
    float r = sNoise(vec3(gP.x * 64.0, gP.y * 2.2 + uTime * 0.35, gP.z * 64.0), 64.0);
    float riv = smoothstep(0.62, 0.74, r) * side * w * uRain;
    gHt += riv * 0.0004;
    gloss = max(gloss, riv);
  }
  #endif
  s.rough = mix(s.rough, 0.06, gloss);
  // beyond the range where beads resolve they average into a general sheen
  s.rough = mix(s.rough, max(s.rough * 0.7, 0.14), w * (1.0 - f1) * 0.8);
  s.albedo *= 1.0 - 0.12 * film;
}

// Porous surfaces soak: darker, more saturated, smoother. The soak has an edge: rain reaches some
// of a wall and not the rest, and on vertical faces it comes down in broad streaks.
// 'lo' is a slow noise value and 'streak' a vertical-streak value the caller already has.
void sWetPorous(inout Surf s, float w, float porosity, float lo, float streak) {
  if (w < 0.01) return;
  float side = 1.0 - smoothstep(0.3, 0.8, abs(gN.y));
  float n = mix(lo, lo * 0.5 + 0.5 * streak, side);
  float k = smoothstep(0.62, 0.38, n - (w - 0.5) * 0.9) * smoothstep(0.0, 0.25, w);
  s.albedo = sSat(s.albedo, 1.0 + 0.3 * k) * mix(1.0, 1.0 - 0.6 * porosity, k);
  s.rough = mix(s.rough, s.rough * 0.45, k);
}

// ---- paint damage, shared by painted metal and painted concrete ----
// One scalar field; rising through it you cross stained paint (halo), then the primer rim, then the
// substrate. 'grad' is the slope of the paint film's broken edge.
struct Chip { float bare; float primer; float halo; vec3 grad; };
float sChipTh(float wear) { return mix(0.74, 0.47, wear) - 0.07 * sSplashBand(); }
// two fetches: the broad field that decides where paint has failed, and the ragged edge detail
float gChipLo = 0.5;    // the broad half of the chip field, for callers that look nearby (rust runs)
vec4 sChipField(vec3 p, float scale) {
  vec4 a = sFbmD(p + 31.7, 1.1 * scale);
  gChipLo = a.x;
  vec4 b = sFbmD(S_ROT * p, 13.0 * scale);
  return vec4(a.x * 0.42 + b.x * 0.58, a.yzw * 0.42 + (b.yzw * S_ROT) * 0.58);
}
Chip sChips(vec3 p, float wear, float scale) {
  Chip k = Chip(0.0, 0.0, 0.0, vec3(0.0));
  if (wear <= 0.001) return k;
  vec4 n = sChipField(p, scale);
  #if SURF_Q > 1
  // the stored field is three octaves; a finer copy keeps chip outlines ragged up close
  vec4 d = sFbmD(p + 5.3, 60.0 * scale);
  n += vec4(d.x - 0.5, d.yzw) * 0.2;
  #endif
  float th = sChipTh(wear);
  float aa = 0.006 + length(n.yzw) * gFp * 1.2;
  k.bare = smoothstep(th, th + aa, n.x);
  k.primer = smoothstep(th - 0.01, th - 0.01 + aa, n.x);
  k.halo = smoothstep(th - 0.16, th, n.x);
  float e = k.primer * (1.0 - k.primer) * 4.0;
  vec3 g = -n.yzw * (e * 1.5 / aa) * 0.00012;
  k.grad = g / max(1.0, length(g));
  return k;
}

#define CLOTH_SLOTS 1
#define CHAR_BODY 1

uniform float uBlood;
uniform vec4 uWound[4];
uniform vec4 uStain[4];
uniform vec3 uDown;
uniform vec3 uAxis;
// A placed sphere as an irregular patch: 1 at its centre, 0 at its edge. 'k' gives each one its own
// long axis and stretch; 'warp' (noise, about -0.5..0.5) pushes the edge in and out, so no two are
// the same shape and none is a disc.
float sPatch(vec4 a, vec3 pr, float k, float warp) {
  if (a.w <= 0.0) return 0.0;
  vec3 v = pr - a.xyz;
  float d2 = dot(v, v);
  if (d2 > a.w * a.w * 4.0) return 0.0;
  vec3 dir = normalize(vec3(sin(k * 2.4 + 0.7), cos(k * 1.7) * 1.3, sin(k * 3.1 + 2.0)));
  float al = dot(v, dir);
  float sq = 0.45 + 0.4 * fract(k * 0.618);
  float d = sqrt(max(d2 - al * al * (1.0 - sq * sq), 0.0)) / (a.w * (0.72 + 0.28 * sq) * clamp(1.0 + warp * 1.1, 0.35, 1.7));
  return 1.0 - smoothstep(0.0, 1.0, d);
}
// Where blood from a source has run: x = envelope (wide at the source, narrowing down), y = how far
// down its length this is (0..1). The trails themselves are cut from this with streak noise.
vec2 sRunEnv(vec4 a, vec3 pr, vec3 down, float k) {
  if (a.w <= 0.0) return vec2(0.0);
  vec3 v = pr - a.xyz; float al = dot(v, down);
  float len = a.w * (2.5 + 5.0 * fract(k * 0.37));
  if (al < -a.w * 0.2 || al > len) return vec2(0.0);
  float t = max(al, 0.0) / len;
  float wid = a.w * mix(0.7, 0.1, sqrt(t));
  float lat = length(v - down * al);
  return vec2((1.0 - smoothstep(wid * 0.4, wid, lat)) * smoothstep(-a.w * 0.2, a.w * 0.3, al) * (1.0 - smoothstep(0.75, 1.0, t)), t);
}


uniform vec4 uChWound[8];
uniform float uChWoundK[8];
uniform vec3 uChWoundN[8];
uniform float uChSever[5];
uniform float uChHat;
// Skin a hat hides (1 cap, 2 campaign hat, 3 beanie): the scalp above the band, and under a beanie
// the tops of the ears. A hat rides its own bone, askew, and the skull's own scale; cutting what
// is under it is what keeps a lump of scalp from coming through the crown.
bool sChHatCut(vec3 pr) {
  if (uChHat < 0.5) return false;
  if (pr.y > (uChHat < 1.5 ? 1.732 : uChHat < 2.5 ? 1.742 : 1.716)) return true;
  return uChHat > 2.5 && pr.y > 1.699 && abs(pr.x) > 0.0765;
}
// the arm of the rest pose: x = distance along it from the shoulder, y = distance from its line
vec2 sChArm(vec3 pr) {
  vec2 v = vec2(abs(pr.x) - 0.186, pr.y - 1.405);
  return vec2(v.x * 0.5646 - v.y * 0.8253, length(vec2(v.x * 0.8253 + v.y * 0.5646, pr.z + 0.012)));
}
// Is this fragment on a severed part (the skin of a hidden bone, collapsed to the joint: what is
// still drawn is the cap stretched over the stump)? Returns 0, or 1 + how far past the cut it was.
float sChStump(vec3 pr) {
  bool L = pr.x >= 0.0;
  if (uChSever[0] > 0.75 && pr.y > 1.54) return 1.0 + (pr.y - 1.54) * 6.0;
  // the jaw alone (a damaged head): the lower face is the stump
  if (uChSever[0] > 0.25 && pr.y < 1.628 && pr.y > 1.555 && pr.z > 0.0 && abs(pr.x) < 0.065) return 1.0 + (1.628 - pr.y) * 9.0;
  vec2 a = sChArm(pr);
  if ((L ? uChSever[1] : uChSever[2]) > 0.5 && a.x > 0.25 && a.y < 0.14 && pr.y < 1.3) return 1.0 + (a.x - 0.25) * 5.0;
  if ((L ? uChSever[3] : uChSever[4]) > 0.5 && pr.y < 0.56) return 1.0 + (0.56 - pr.y) * 5.0;
  return 0.0;
}
// A lock of wet hair on a card, drawn as a function of the card's (u, v), so there is no texel to
// stair-step however close the camera comes. u runs across one of eight locks, v from root to tip.
// The lock wanders and narrows to a point, and is made of strands that run its length, end at
// different places and thin as they end: its tip is a few hairs, its sides are hair, never the cut
// edge of a strip of paper. The cover and the knot (aSurf.z > 2) are one sheet of the same strands:
// only their ends are cut (the fringe at the hairline).
// Returns the coverage 0..1; gHair = (the strand's tone, where across the lock -1..1, where across
// the strand -0.5..0.5, how well single strands resolve 0..1).
vec4 gHair = vec4(1.0, 0.0, 0.0, 0.0);
float gHairThr = 0.5;
float sChLock() {
  bool cover = gA.z > 2.0;
  float lu = gA.x * 8.0, id = floor(lu), c = fract(lu) - 0.5, v = gA.y;
  float seed = cover ? 0.0 : fract(gA.z * 37.0);       // (a lock's own; the cover's shade varies across it)
  float E = cover ? 0.5 : 0.48 * (1.0 - 0.82 * smoothstep(0.3, 1.0, v));
  float cw = cover ? 0.0 : 0.075 * sin(v * 4.6 + id * 2.4 + seed * 40.0) * smoothstep(0.2, 1.0, v);
  float q = (c - cw) / E;
  float NS = cover ? 11.0 : 9.0;
  float sc = (q * 0.5 + 0.5) * NS;
  sc += 0.33 * sin(sc * 2.3 + id * 1.7 + seed * 9.0);       // strands of unequal width
  float si = floor(sc), sf = fract(sc) - 0.5;
  vec3 h = sHash3(ivec3(int(si), int(id) + int(seed * 977.0), 3));
  // most strands run nearly to the tip, the outer ones stop sooner
  float L = cover ? mix(0.5, 1.0, h.x) : 1.0 - 0.5 * h.x - 0.28 * q * q;
  float ht = 0.5 - 0.44 * smoothstep(L - 0.28, L, v);
  float wS = fwidth(sc);
  float one = clamp(0.5 + (ht - abs(sf)) / max(wS, 1e-4), 0.0, 1.0) * step(v, L);
  float res = 1.0 - smoothstep(0.5, 1.4, wS);
  float a = cover && v < 0.46 ? 1.0 : one;
  if (!cover) a *= clamp(0.5 + (1.0 - abs(q)) * E / max(fwidth(c), 1e-4), 0.0, 1.0);
  gHair = vec4(0.62 + 0.5 * h.y, cover ? 0.0 : clamp(q, -1.0, 1.0), sf, res);
  // partly covered pixels are kept or dropped against a threshold fixed to the strand (in lengths
  // of a few millimetres), so an edge breaks up into hairs and does not crawl
  gHairThr = 0.3 + 0.4 * sHash3(ivec3(int(si) + 31 * int(id), int(floor(v * 16.0 + h.z * 9.0)), 11)).x;
  return a;
}
bool sChHairGone() { float a = sChLock(); return a < gHairThr; }
// The nearest wound: x = distance in radii (0 centre, 1 edge; 9 = none), y = kind, z = radius;
// gWdDir = unit direction away from its centre in rest space.
vec3 gWdDir = vec3(0.0);
// reach: cloth stands off the skin, so along the wound's own outward normal that much distance is
// forgiven (the wound is the path of the shot, not a ball on the skin): 0 for skin.
vec3 sChWoundAtR(vec3 pr, float reach) {
  vec3 best = vec3(9.0, 0.0, 0.0);
  for (int i = 0; i < 8; i++) {
    vec4 w = uChWound[i];
    if (w.w <= 0.0) continue;
    vec3 v = pr - w.xyz;
    if (reach > 0.0) v -= uChWoundN[i] * clamp(dot(v, uChWoundN[i]), -0.015, reach);
    float d = length(v) / w.w;
    if (d < best.x) { best = vec3(d, uChWoundK[i], w.w); gWdDir = v / max(length(v), 1e-5); }
  }
  return best;
}
vec3 sChWoundAt(vec3 pr) { return sChWoundAtR(pr, 0.0); }
// the nearest wound as cloth meets it (x = distance in radii, through any layer worn over the skin)
vec3 sChWoundCloth(vec3 pr) { return sChWoundAtR(pr, 0.085); }
// how much blood the cloth round a wound has taken up: 1 at the hole, 0 from two radii out
// (ragged, and further down than up: it ran. A plain falloff soaked a perfect ring round the hole.)
float sChWound(vec3 pr) {
  vec3 w = sChWoundCloth(pr);
  if (w.x > 3.6) return 0.0;
  float n = sFbm(pr + 23.0, 1.4 / max(w.z, 0.01)), n2 = sFbm(pr + 61.0, 5.0 / max(w.z, 0.01));
  float d = w.x * (1.0 + 0.4 * gWdDir.y) + (n - 0.5) * 1.5 + (n2 - 0.5) * 0.5;
  return 1.0 - smoothstep(0.45, 1.7, d);
}
// A severed part is cut away, raggedly, a little past the joint; the stump is closed by a cap of
// flesh inside the limb (eyes.js: buildCore). The jaw alone is not cut: its skin is the wound.
bool sChCut(vec3 pr, float n) {
  float st = sChStump(pr);
  if (st <= 0.0) return false;
  if (uChSever[0] > 0.25 && uChSever[0] < 0.75 && pr.y > 1.5) return false;
  return st > 1.0 + 0.1 * n;
}


uniform sampler2D tChNA;
uniform sampler2D tChAR;
uniform sampler2D tChTC;
uniform sampler2D tChCloth;
uniform sampler2D tChHair;
uniform float uChBlood[6];
uniform vec3 uChHair;
uniform vec2 uChHairAmt;
uniform vec3 uChTint;
uniform float uChRot;
uniform float uChGrime;
uniform vec4 uChEye;
uniform float uChFar;
uniform float uChDebug;
// x = how much blood this body part carries here, y = 1 if any part carries any
vec2 sChPartBlood(vec3 pr) {
  float any = uChBlood[0] + uChBlood[1] + uChBlood[2] + uChBlood[3] + uChBlood[4] + uChBlood[5];
  if (any <= 0.0) return vec2(0.0);
  bool L = pr.x >= 0.0;
  float head = smoothstep(1.47, 1.53, pr.y);
  vec2 a = sChArm(pr);
  float arm = smoothstep(-0.02, 0.07, a.x) * (1.0 - smoothstep(0.075, 0.125, a.y)) * (1.0 - head);
  float leg = (1.0 - smoothstep(0.84, 0.96, pr.y)) * (1.0 - arm);
  float torso = (1.0 - head) * (1.0 - arm) * (1.0 - leg);
  return vec2(uChBlood[0] * head + uChBlood[1] * torso + (L ? uChBlood[2] : uChBlood[3]) * arm + (L ? uChBlood[4] : uChBlood[5]) * leg, 1.0);
}
// baked slopes (encoded tan along u and v) -> height derivatives on screen, metres per pixel
vec2 sChSlope(vec2 enc) {
  vec2 t = enc * 2.0 - 1.0;
  t = sign(t) * t * t * 3.0;
  vec3 dPx = dFdx(vSP), dPy = dFdy(vSP);
  vec2 dUx = dFdx(vSUv), dUy = dFdy(vSUv);
  float det = dUx.x * dUy.y - dUx.y * dUy.x;
  if (abs(det) < 1e-14) return vec2(0.0);
  vec3 Tu = (dPx * dUy.y - dPy * dUx.y) / det, Tv = (dPy * dUx.x - dPx * dUy.x) / det;
  vec2 m = t * vec2(length(Tu), length(Tv));
  return vec2(dot(m, dUx), dot(m, dUy));
}


