uniform float uSplash;
uniform float uGroundY;
uniform vec3 uSeedOff;

struct Surf { vec3 albedo; float rough; float metal; vec3 grad; vec2 dH; vec3 emissive; float alpha; float ao; };

// per-fragment context, set once in main()
vec3 gP;    // noise-space position (world, or object/rest space) plus the seed offset
vec3 gN;    // geometric normal in noise space
vec3 gNw;   // geometric normal in world space
vec3 gWp;   // world position
vec3 gV;    // world direction to the camera
vec4 gA;    // aSurf vertex masks: x wear/edge, y blood, z grip zone
float gNdv;

#define NZ_BASE 8.0
#define NZ_GRAD 4.0
#define NZ_VORO 16.0
// SURF_Q: 2 = high, 1 = medium, 0 = low (from G.quality). Optional layers are dropped below 2.
#ifndef SURF_Q
  #define SURF_Q 2
#endif

float gFp = 0.001;

vec3 sHash3(ivec3 c) {
  uvec3 x = uvec3(c);
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  x = ((x >> 8U) ^ x.yzx) * 1103515245U;
  return vec3(x) * (1.0 / 4294967295.0);
}
float sHash1(ivec3 c) { return sHash3(c).x; }
vec3 sHash2(ivec2 c) { return sHash3(ivec3(c, 7)); }

float sFade(float freq) { return 1.0 - smoothstep(0.16, 0.5, gFp * freq); }

const mat3 S_ROT = mat3(0.00, 0.80, 0.60, -0.80, 0.36, -0.48, -0.60, -0.48, 0.64);

// ---- texture-backed noise (noiseTex.js). These replace the procedural functions above at runtime:
// one fetch each, with the mip level chosen from gFp, so they are safe inside branches and fade to
// their mean with distance by themselves.
uniform highp sampler3D tNzA;
uniform highp sampler3D tNzB;
float gLod = 0.0;      // mip level of a volume sampled at one tile per unit of noise space

// fbm, three octaves up from 'freq' cycles per unit: x = value (mean 0.5), yzw = gradient per unit of p
vec4 sFbmD(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  vec4 t = textureLod(tNzA, p * sc, gLod + log2(sc));
  return vec4(t.x, (t.yzw - 0.5) * (2.0 * NZ_GRAD * freq));
}
float sFbm(vec3 p, float freq) {
  float sc = freq * (1.0 / NZ_BASE);
  return textureLod(tNzA, p * sc, gLod + log2(sc)).x;
}
// the same field with different frequencies across and along a direction
vec4 sAnisoD(vec3 p, vec3 dir, float perp, float along) {
  vec3 q = p * perp + dir * (dot(p, dir) * (along - perp));
  vec4 t = textureLod(tNzA, q * (1.0 / NZ_BASE), gLod + log2(max(perp, along) * (1.0 / NZ_BASE)));
  vec3 g = (t.yzw - 0.5) * (2.0 * NZ_GRAD);
  return vec4(t.x, g * perp + dir * (dot(g, dir) * (along - perp)));
}
// one octave of gradient noise; q is in lattice cells, fmax the largest scale applied to get there
float sNoise(vec3 q, float fmax) {
  return textureLod(tNzB, q * (1.0 / NZ_BASE), gLod + log2(fmax * (1.0 / NZ_BASE))).a;
}
// voronoi, 'cells' per unit: x = F1, y = F2 - F1 (0 on cell edges), z = cell id, w = unrelated noise
vec4 sVoro(vec3 p, float cells) {
  float sc = cells * (1.0 / NZ_VORO);
  return textureLod(tNzB, p * sc, gLod + log2(sc));
}
// Sparse round domes (water beads, sand grains, pills): jittered spheres on a 3D grid, cut by the
// surface. Analytic and exact at any distance from one hash: each sphere stays inside its own cell, so
// only that cell is tested. 'amount' is the fraction of cells that hold one.
// x = coverage 0..1, y = dome height 0..1, z = radius in cells, w = per-dome random.
vec3 gDomeSlope = vec3(0.0);   // slope of the last dome evaluated (noise space, per cell)
vec4 sDomes(vec3 p, float cells, float amount) {
  vec3 q = p * cells;
  vec3 fl = floor(q);
  vec3 h = sHash3(ivec3(fl));
  float pick = fract(h.x * 7.31 + h.y * 3.17);
  vec3 r = q - (fl + 0.5 + (h - 0.5) * 0.4);
  float rad = 0.12 + 0.17 * fract(h.z * 5.3 + pick);
  float t = 1.0 - dot(r, r) / (rad * rad);
  gDomeSlope = vec3(0.0);
  if (pick > amount || t <= 0.0) return vec4(0.0, 0.0, rad, 0.0);
  gDomeSlope = -3.0 * t * r / rad;
  return vec4(smoothstep(0.0, 0.25, t), t, rad, fract(h.z * 11.3));
}
vec3 gGradX = vec3(0.0);       // extra analytic slope from shared layers (beads), added to Surf.grad
float gHt = 0.0;       // extra relief in metres, differentiated on screen once (beads, rivulets, pits)

// Straight hairline scratches along 'dir': the one-octave field squeezed along that direction, so
// each lattice cell becomes a long thin sliver, and only the brightest slivers are kept.
float sScratches(vec3 p, vec3 dir, float across, float along, float density) {
  float f = sFade(across);
  if (f <= 0.0) return 0.0;
  float n = sNoise(p * across - dir * dot(p, dir) * (across - along), across);
  return smoothstep(1.0 - density, 1.0 - density * 0.6, n) * f;
}

// Thin winding line along the 0.5 iso-contour of a noise field: returns distance to the line in the
// field's own space units (metres if p is metres), using the analytic gradient for constant width.
float sIsoDist(vec4 n) { return abs(n.x - 0.5) / max(length(n.yzw), 1e-4); }

// B-spline bicubic from four bilinear taps. The texture must use linear filtering.
vec4 sBicubic(sampler2D t, vec2 uv, float res) {
  vec2 st = uv * res - 0.5; vec2 i = floor(st); vec2 f = st - i;
  vec2 f2 = f * f, f3 = f2 * f;
  vec2 w0 = (1.0 - f) * (1.0 - f) * (1.0 - f) / 6.0;
  vec2 w1 = (3.0 * f3 - 6.0 * f2 + 4.0) / 6.0;
  vec2 w3 = f3 / 6.0;
  vec2 w2 = 1.0 - w0 - w1 - w3;
  vec2 g0 = w0 + w1, g1 = w2 + w3;
  vec2 h0 = (i - 0.5 + w1 / g0) / res, h1 = (i + 1.5 + w3 / g1) / res;
  return g0.y * (g0.x * texture2D(t, h0) + g1.x * texture2D(t, vec2(h1.x, h0.y)))
       + g1.y * (g0.x * texture2D(t, vec2(h0.x, h1.y)) + g1.x * texture2D(t, h1));
}

float sLuma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
vec3 sSat(vec3 c, float k) { return max(mix(vec3(sLuma(c)), c, k), 0.0); }


// ---- rain ----
// how much rain reaches this fragment: up-facing most, undersides least, nothing under shelter
float sExposure() { return (1.0 - uShelter) * mix(0.25, 1.0, smoothstep(-0.35, 0.65, gNw.y)); }
// 1 where the object meets the ground, gone by about half a metre, with a broken top edge
float gSplash = -1.0;     // computed once per fragment; several layers ask for it
float sSplashBand() {
  if (gSplash >= 0.0) return gSplash;
  float h = gWp.y - uGroundY;
  gSplash = 0.0;
  if (h < 0.8 && uSplash > 0.0) gSplash = uSplash * (1.0 - smoothstep(0.02, 0.3 + 0.35 * sNoise(gP * vec3(7.0, 2.0, 7.0), 7.0), h));
  return gSplash;
}
float sWetAmount() { return clamp(uWetness * max(sExposure(), sSplashBand() * 0.9), 0.0, 1.0); }

// Water beads standing on a surface: coverage, and their slope added to the normal. No fetch.
float sBeadLayer(vec3 p, float cells, float amount, float lift) {
  vec4 b = sDomes(p, cells, amount);
  gGradX += gDomeSlope * lift;
  return b.x;
}

// Non-porous surfaces: water sits on top as a film, beads, and rivulets on vertical faces.
// 'lo' is any slow noise value the caller already has (it places the film).
void sWetHard(inout Surf s, float w, float lo) {
  if (w < 0.01) return;
  float up = smoothstep(0.3, 0.9, gNw.y);
  float f1 = sFade(260.0);
  float film = w * mix(0.25, 0.85, up) * smoothstep(0.3, 0.7, lo * 0.6 + w * 0.5);
  float gloss = film;
  #if SURF_Q > 0
  if (f1 > 0.0) gloss = max(gloss, sBeadLayer(gP, 120.0, 0.5 * w, 0.9) * f1);
  #endif
  #if SURF_Q > 1
  if (sFade(900.0) > 0.3) gloss = max(gloss, sBeadLayer(gP + 3.7, 430.0, 0.65 * w, 0.9));
  #endif
  #if !defined(SURF_LOCAL) && SURF_Q > 0
  float side = 1.0 - smoothstep(0.25, 0.75, abs(gNw.y));
  if (side > 0.01 && uRain > 0.0) {
    float r = sNoise(vec3(gP.x * 64.0, gP.y * 2.2 + uTime * 0.35, gP.z * 64.0), 64.0);
    float riv = smoothstep(0.62, 0.74, r) * side * w * uRain;
    gHt += riv * 0.0004;
    gloss = max(gloss, riv);
  }
  #endif
  s.rough = mix(s.rough, 0.06, gloss);
  // beyond the range where beads resolve they average into a general sheen
  s.rough = mix(s.rough, max(s.rough * 0.7, 0.14), w * (1.0 - f1) * 0.8);
  s.albedo *= 1.0 - 0.12 * film;
}

// Porous surfaces soak: darker, more saturated, smoother. The soak has an edge: rain reaches some
// of a wall and not the rest, and on vertical faces it comes down in broad streaks.
// 'lo' is a slow noise value and 'streak' a vertical-streak value the caller already has.
void sWetPorous(inout Surf s, float w, float porosity, float lo, float streak) {
  if (w < 0.01) return;
  float side = 1.0 - smoothstep(0.3, 0.8, abs(gN.y));
  float n = mix(lo, lo * 0.5 + 0.5 * streak, side);
  float k = smoothstep(0.62, 0.38, n - (w - 0.5) * 0.9) * smoothstep(0.0, 0.25, w);
  s.albedo = sSat(s.albedo, 1.0 + 0.3 * k) * mix(1.0, 1.0 - 0.6 * porosity, k);
  s.rough = mix(s.rough, s.rough * 0.45, k);
}

// ---- paint damage, shared by painted metal and painted concrete ----
// One scalar field; rising through it you cross stained paint (halo), then the primer rim, then the
// substrate. 'grad' is the slope of the paint film's broken edge.
struct Chip { float bare; float primer; float halo; vec3 grad; };
float sChipTh(float wear) { return mix(0.74, 0.47, wear) - 0.07 * sSplashBand(); }
// two fetches: the broad field that decides where paint has failed, and the ragged edge detail
float gChipLo = 0.5;    // the broad half of the chip field, for callers that look nearby (rust runs)
vec4 sChipField(vec3 p, float scale) {
  vec4 a = sFbmD(p + 31.7, 1.1 * scale);
  gChipLo = a.x;
  vec4 b = sFbmD(S_ROT * p, 13.0 * scale);
  return vec4(a.x * 0.42 + b.x * 0.58, a.yzw * 0.42 + (b.yzw * S_ROT) * 0.58);
}
Chip sChips(vec3 p, float wear, float scale) {
  Chip k = Chip(0.0, 0.0, 0.0, vec3(0.0));
  if (wear <= 0.001) return k;
  vec4 n = sChipField(p, scale);
  #if SURF_Q > 1
  // the stored field is three octaves; a finer copy keeps chip outlines ragged up close
  vec4 d = sFbmD(p + 5.3, 60.0 * scale);
  n += vec4(d.x - 0.5, d.yzw) * 0.2;
  #endif
  float th = sChipTh(wear);
  float aa = 0.006 + length(n.yzw) * gFp * 1.2;
  k.bare = smoothstep(th, th + aa, n.x);
  k.primer = smoothstep(th - 0.01, th - 0.01 + aa, n.x);
  k.halo = smoothstep(th - 0.16, th, n.x);
  float e = k.primer * (1.0 - k.primer) * 4.0;
  vec3 g = -n.yzw * (e * 1.5 / aa) * 0.00012;
  k.grad = g / max(1.0, length(g));
  return k;
}


#define NMARK 32
#define AGG_UV 1.328125
#define AGG_SLOPE 3.0
#if SURF_Q > 1
  #define RING_LAYERS 2
  #define REFL_TAPS 12
#else
  #define RING_LAYERS 1
  #define REFL_TAPS 6
#endif
uniform sampler2D tAgg;
uniform sampler2D tGroundMask;
uniform vec4 uMaskRect;
uniform float uMaskRes;
uniform sampler2D tGDetail;   // r stain potential, g wheel polish, b patch (0.5 = saw cut), a crack corridor (0.5 = none)
uniform sampler2D tGCrack;    // rg offset to the nearest crack centre line
uniform vec4 uGDetailRect;    // minX, minZ, 1/width, 1/depth
uniform float uGCrackRange;   // metres per unit of tGCrack
uniform sampler2D tGBlood;    // r: blood lying on the surface, over its own rectangle
uniform vec4 uGBloodRect;     // minX, minZ, 1/width, 1/depth (all zero: none)
uniform mat4 uReflMatrix;
uniform sampler2D tReflection;
uniform float uReflOn;
uniform vec4 uMarkA[NMARK];
uniform vec4 uMarkB[NMARK];
uniform int uMarkCount;
uniform vec3 uGTint;
uniform float uGPuddle;
float gWater = 0.0;
float gSoak = 0.0;
float gOilFilm = 0.0;
vec2 gRip = vec2(0.0);
float gFilmN = 0.0;
float gGloss = 0.0;

// expanding rain rings: slope of the water surface (x, z)
vec2 sRings(vec2 p, float t, float rain) {
  vec2 g = vec2(0.0);
  for (int L = 0; L < RING_LAYERS; L++) {
    float fq = L == 0 ? 6.5 : 10.5;
    vec2 q = p * fq + float(L) * 17.3;
    ivec2 c = ivec2(floor(q)); vec2 f = fract(q);
    for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {
      vec3 h = sHash3(ivec3(c + ivec2(i, j), L + 3));
      if (fract(h.z * 5.7 + h.x) > rain) continue;
      float ph = fract(t * (0.9 + 0.5 * h.z) + h.y * 9.0);
      vec2 d = f - (vec2(i, j) + 0.15 + 0.7 * h.xy);
      float r = length(d);
      float x = (r - ph * 0.9) * 30.0;
      g += (d / max(r, 1e-3)) * cos(x) * exp(-x * x * 0.3) * (1.0 - ph) * (1.0 - ph);
    }
  }
  return g;
}

void surfaceMain(inout Surf s) {
  vec2 xz = gP.xz;
  vec3 p2 = vec3(xz.x, 0.0, xz.y);
  vec4 mk = sBicubic(tGroundMask, (xz - uMaskRect.xy) * uMaskRect.zw, uMaskRes);
  // GROUND_DETAIL is defined only on a material that was given a level map. Everything that reads
  // the level's maps is inside such a block, so the plain ground compiles to what it always was.
  #ifdef GROUND_DETAIL
  vec2 duv = (xz - uGDetailRect.xy) * uGDetailRect.zw;
  vec4 dt = texture2D(tGDetail, duv);
  vec2 buv = (xz - uGBloodRect.xy) * uGBloodRect.zw;
  float bl = 0.0;
  if (buv.x > 0.0 && buv.x < 1.0 && buv.y > 0.0 && buv.y < 1.0) bl = textureLod(tGBlood, buv, log2(gFp * uGBloodRect.z * 1024.0)).r;
  #endif

  vec4 mo = sFbmD(p2, 0.55);
  float mott = mo.x;
  #if SURF_Q > 0
  vec4 fine = sFbmD(p2, 420.0);
  float hd = sFbm(S_ROT * p2 + 2.0, 9.0);        // a finer field: keeps shorelines and edges broken
  #else
  vec4 fine = vec4(0.5, 0.0, 0.0, 0.0);
  float hd = 0.5;
  #endif
  vec4 hn = sFbmD(p2 + 5.0, 1.1);

  #ifdef GROUND_DETAIL
  // ---- patch repairs: a newer, blacker, finer mix let into the old surface along a saw cut
  float pe = dt.b + (hd - 0.5) * 0.1 * step(0.02, dt.b);
  float repair = smoothstep(0.47, 0.53, pe);
  float cut = abs(pe - 0.5);                      // 1 unit = 16 cm across the cut
  float polish = dt.g;
  #endif

  // ---- aggregate: angular crushed stone, flat-topped and tilted, set in darker binder. One fetch
  // of the baked stone field (height, slope, tone); two unrelated slow fields hide its 0.75 m tile.
  // A patch reads the same field 1.8 times finer and from somewhere else.
  float fAgg = sFade(170.0);
  #ifdef GROUND_DETAIL
  float pk = step(0.5, pe);
  vec4 ag = texture2D(tAgg, xz * (AGG_UV * (1.0 + 0.8 * pk)) + pk * 0.37); // (the one-pixel mip slip along the cut is under the joint)
  #else
  vec4 ag = texture2D(tAgg, xz * AGG_UV);
  #endif
  float h1 = ag.r;
  vec2 g2 = (ag.gb - 0.5) * (2.0 * AGG_SLOPE) * fAgg;
  float micro = mix(0.5, h1, fAgg);

  float wear = clamp(mk.a + (mott - 0.5) * 0.4, 0.0, 1.0);
  #ifdef GROUND_DETAIL
  wear *= 1.0 - 0.4 * repair;
  #endif
  float expose = mix(0.55, 0.95, wear);
  vec3 binder = vec3(0.02, 0.02, 0.022);
  float tone = ag.a * ag.a;
  vec3 stoneCol = mix(0.035, 0.24, tone * tone + 0.15 * tone) * mix(vec3(1.0, 0.94, 0.86), vec3(0.86, 0.94, 1.06), smoothstep(0.3, 0.7, ag.a));
  vec3 alb = mix(binder, stoneCol, h1 * expose);
  alb = mix(mix(binder, vec3(0.085), 0.6 * expose), alb, fAgg);
  alb *= (0.75 + 0.5 * mott) * (0.7 + 0.6 * fine.x) * uGTint;
  float rough = mix(0.93, 0.8, wear) - h1 * 0.1 * wear * fAgg;
  // pitted stone faces, gritty binder
  g2 += fine.yw * 0.0009 * (1.0 - 0.4 * h1);
  #ifdef GROUND_DETAIL
  alb *= 1.0 - 0.1 * repair;
  rough -= 0.05 * repair;
  g2 *= 1.0 - 0.35 * repair;
  micro = mix(micro, 0.65 * micro, repair);
  // ---- wheel polish: where tyres run the stone tops are worn smooth and the binder is tight:
  // a little darker, a good deal smoother, flatter
  alb *= 1.0 - 0.45 * polish;
  rough -= 0.18 * polish;
  micro = mix(micro, 0.22, 0.65 * polish);
  g2 *= 1.0 - 0.45 * polish;
  #endif

  // ---- cracks
  float crack = 0.0;      // open crack: a dark line
  float tar = 0.0;        // tar poured over a crack or round a repair
  float ravel = 0.0;      // the crumbled, damper shoulder of a crack
  float H0 = 0.5;
  #ifdef GROUND_DETAIL
  H0 = hn.x;
  #endif
  #if SURF_Q > 0
  #ifdef GROUND_DETAIL
  {
    // authored: a coarse corridor says a crack is near and how strong; the offset map says exactly where
    float ca = dt.a * 255.0;
    float corr = abs(ca - 127.5) / 127.5;
    float fN = 1.0 - smoothstep(0.012, 0.035, gFp);            // near enough to resolve a line
    if (corr > 0.03) {
      float sealed = step(127.5, ca);
      float dv = (1.0 - corr) * 0.085;                         // far away: the corridor's own falloff will do
      if (fN > 0.0) {
        vec2 v = (textureLod(tGCrack, duv, 0.0).rg * 255.0 - 128.0) * (uGCrackRange / 127.0);
        dv = mix(dv, length(v), fN);
      }
      float st = smoothstep(0.03, 0.5, corr);
      // open: hairline at the tips to a few millimetres on the trunk, never even
      // (it opens and closes along its length with the metre-scale field, and frays with the fine one)
      float w = 0.0004 + 0.0036 * corr * smoothstep(0.3, 0.7, hn.x + (hd - 0.5) * 0.5) * (0.4 + 0.6 * fine.x);
      // (a line thinner than a pixel covers only its share of it)
      crack = (1.0 - smoothstep(w * 0.5, w + gFp * 0.8, dv)) * min(1.0, 2.5 * w / (w + gFp)) * (1.0 - sealed) * st * fN;
      ravel = (1.0 - smoothstep(0.003, 0.02 + 0.03 * hd, dv)) * st * (1.0 - 0.6 * sealed) * fN;
      // sealed: an over-banded ribbon of tar, a couple of centimetres wide, pooled in places
      float tw = 0.006 + 0.012 * smoothstep(0.3, 0.75, hd) + 0.004 * corr;
      tar = (1.0 - smoothstep(tw * 0.7, tw + gFp * 0.5, dv)) * min(1.0, 3.0 * tw / (tw + gFp)) * sealed * st * mix(smoothstep(0.75, 0.95, corr), 1.0, fN);
    }
    // the saw cut round a repair: tar along most of it, a bare joint where it was missed or has gone
    if (dt.b > 0.02) {
      float sealHere = smoothstep(0.47, 0.55, hn.x + (mott - 0.5) * 0.5);
      float tw = 0.05 + 0.1 * smoothstep(0.35, 0.7, hd);       // 0.8 to 2.4 cm either side
      tar = max(tar, (1.0 - smoothstep(tw * 0.65, tw + gFp * 4.0, cut)) * sealHere);
      crack = max(crack, (1.0 - smoothstep(0.004, 0.012 + gFp * 5.0, cut)) * min(1.0, 0.004 / (0.002 + gFp)) * (1.0 - sealHere) * smoothstep(0.4, 0.6, hd + mott - 0.5) * fN);
    }
  }
  #else
  {
    // no level map: the 0.5 contour of a slow field, only in the areas that have failed
    vec4 cw = sFbmD(p2 + 40.0, 0.3);
    H0 = cw.x;
    float cmask = smoothstep(0.45, 0.6, sFbm(p2 + 80.0, 0.12)) * sFade(110.0);
    if (cmask > 0.0) {
      // the stored field is smooth at this scale: a finer copy makes the line wander
      vec4 cd = sFbmD(p2 + 9.0, 2.6);
      vec4 cq = vec4(cw.x + (cd.x - 0.5) * 0.16, cw.yzw + cd.yzw * 0.16);
      float cwid = 0.0015 + 0.003 * fine.x;
      crack = (1.0 - smoothstep(cwid * 0.5, cwid + gFp, sIsoDist(cq))) * cmask;
    }
  }
  #endif
  #ifdef GROUND_DETAIL
  alb *= (1.0 - 0.65 * crack) * (1.0 - 0.14 * ravel);
  alb = mix(alb, vec3(0.02, 0.02, 0.021), 0.85 * tar);
  rough = mix(rough, 0.42, tar);
  micro = mix(micro, 0.12, tar);
  g2 *= 1.0 - 0.9 * tar;
  #else
  alb *= 1.0 - 0.7 * crack;
  #endif
  #endif

  // ---- painted markings and tyre marks
  float paint = 0.0; vec3 pcol = vec3(0.0); float skid = 0.0;
  float pw = -1.0;      // paint-wear field, fetched once and only near a marking
  float aa = gFp + 0.0015;
  for (int i = 0; i < NMARK; i++) {
    if (i >= uMarkCount) break;
    vec4 a = uMarkA[i], b = uMarkB[i];
    vec2 q = xz - a.xy;
    q = vec2(q.x * b.x + q.y * b.y, q.y * b.x - q.x * b.y);
    vec2 e = abs(q) - a.zw;
    float sd = max(e.x, e.y);
    if (sd > 0.05) continue;
    if (b.z > 3.5) {
      // an arrow along +x: a shaft, then a head tapering from the full width to the tip
      float hs = a.z * 0.05;
      sd = max(e.x, abs(q.y) - (q.x < hs ? a.w * 0.32 : a.w * (1.0 - (q.x - hs) / (a.z - hs))));
    }
    if (pw < 0.0) pw = clamp(0.5 + (sFbm(p2 + 15.0, 26.0) - 0.5) * 1.5, 0.0, 1.0);
    if (b.z > 1.5 && b.z < 2.5) {
      float tr = smoothstep(0.42, 0.58, abs(q.y) / a.w);
      float st = sNoise(vec3(q.x * 2.0, q.y * 90.0, float(i)), 90.0);
      float ends = 1.0 - smoothstep(0.4, 1.0, abs(q.x) / a.z);
      skid = max(skid, tr * ends * smoothstep(0.25, 0.7, st) * (1.0 - smoothstep(-0.02, 0.0, sd)) * (1.0 - b.w));
    } else {
      float m = 1.0 - smoothstep(-aa, aa, sd + (pw - 0.5) * 0.012);
      if (b.z > 2.5 && b.z < 3.5) m *= smoothstep(-aa * 1.6, aa * 1.6, abs(fract((q.x + q.y) * 1.6) - 0.5) - 0.25);
      // paint flakes off the stone tops first, and faster in the wheel lanes
      float th = b.w * (0.6 + 0.4 * wear);
      float keep = clamp((pw - 0.3) * 2.5, 0.0, 1.0) * 0.65 + mix(0.5, 1.0 - h1, fAgg) * 0.35;
      m *= smoothstep(th - 0.15, th + 0.05, keep);
      if (m > paint) { paint = m; pcol = b.z < 0.5 || b.z > 3.5 ? vec3(0.5, 0.5, 0.47) : vec3(0.5, 0.33, 0.02); }
    }
