  float dirt = uGlDirt * clamp(dn * 1.1 - 0.2 + sSplashBand() * 0.8 - 0.3 * smoothstep(0.5, 0.8, washed) * w, 0.0, 1.0);
  float mist = uGlMist * (0.6 + 0.4 * (1.0 - dn)) * (1.0 - 0.9 * dr.y) * (1.0 - drop);
